struct PlaceOrderRequest { std::string customer; std::vector<OrderLine> lines; };
class OrderFacade {                       // server side, no domain logic
 public:
  OrderConfirmation placeOrder(const PlaceOrderRequest& req) {
    Order order = Order::Create(req.customer, req.lines);       // fine-grained model
    return ToConfirmation(order, Price(order));                  // transfer object
  }
};
class OrderFacadeProxy {                  // client side: marshal, call, unmarshal
 public:
  OrderConfirmation placeOrder(const PlaceOrderRequest& req) const;
};
